    28→        public Signature(ReadOnlySpan<byte> bytes)
    29→        {
    30→            ArgumentOutOfRangeException.ThrowIfNotEqual(bytes.Length, 65);
    31→
    32→            bytes[..64].CopyTo(Bytes);
    33→            V = bytes[64];
    34→        }
