   323→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec)
   324→    {
   325→        Signature? signature = transaction.Signature;
   326→        if (signature is null)
   327→        {
   328→            return TxErrorMessages.InvalidTxSignature;
   329→        }
   330→
   331→        UInt256 sValue = new(signature.SAsSpan, isBigEndian: true);
